export const P061_SEAL_STATUS='reviewed-dom-run-sealed';
export const P061_SHARED_DEPENDENCIES=P061_REVIEWED_DOM_SEAL.sharedDependencies;
export const P061_RUN_INPUTS=P061_REVIEWED_DOM_SEAL.runInputs;
export const P061_RUN_OUTPUTS=P061_REVIEWED_DOM_SEAL.runOutputs;
export const P061_PAGE_INPUT_PATHS=P061_REVIEWED_DOM_SEAL.pageInputPaths;
export const P061_RUN=P061_REVIEWED_DOM_SEAL.run;
export const P061_MEMBER=P061_REVIEWED_DOM_SEAL.member;
/** One pre-existing host-v10 tool is also a frozen P061 run input. Both proofs
 * retain the same bytes; no new host/page path overlap is permitted. */
export const P061_INHERITED_HOST_OVERLAP=Object.freeze({
 path:'scripts/build-g4-l3-embedded-audio-archive.mjs',bytes:49846,
 sha256:'2c04bba5dc5e2c5870305ce5d4429457548712c5843e1bdf2dd11c8b5d3658cf',
});
demand(P061_REVIEWED_DOM_SEAL.runInputs.length===179&&
 P061_REVIEWED_DOM_SEAL.runOutputs.length===22&&
 P061_REVIEWED_DOM_SEAL.sharedDependencies.length===6&&
 P061_REVIEWED_DOM_SEAL.pageInputPaths.length===188,
 'exact reviewed DOM closure cardinalities');
demand(P061_REVIEWED_DOM_SEAL.runInputs.filter(pin=>
 pin.path===P061_INHERITED_HOST_OVERLAP.path).length===1,
 'one inherited host tool in DOM run');
same(P061_REVIEWED_DOM_SEAL.runInputs.find(pin=>
 pin.path===P061_INHERITED_HOST_OVERLAP.path),P061_INHERITED_HOST_OVERLAP,
 'exact inherited host tool bytes');
const requireSeal=()=>{
 demand(P061_REVIEWED_DOM_SEAL!==null,'reviewed DOM run/member/input pins not sealed');
 return P061_REVIEWED_DOM_SEAL;
};

export function validateP061AdmissionSemantics(packet,registration){
 demand(packet?.schemaVersion===1&&packet.calibrationId===P061_ADMISSION_CALIBRATION&&
  packet.sourceRoot===P061_SOURCE_ROOT&&packet.scope==='private-engineering'&&
  packet.deploymentScope==='local-only','exact local P061 identity');
 same(packet.source,P061_SOURCE,'source SWF');same(packet.sourceXml,P061_XML,'lesson source XML');
 same(packet.selectedPages,[{animationId:P061_ADMISSION_ID,placementId:P061_ADMISSION_ID,
  assetId:`swf-${P061_SOURCE.sha256}`,stableLessonKey:'shared-nms002-l02',
  sourceSha256:P061_SOURCE.sha256,moduleCode:'NMS002',lessonNumber:2,
  globalPageOrdinal:61,sourceOccurrence:61,sectionCode:'TS',sectionPageOrdinal:7,
  complexityLane:'behavior-heavy',runtime:P061_RUNTIME}],
 'exact P061 placement and DOM runtime');
 const entry=packet.entry,artifacts=entry?.artifacts;
 same(Object.keys(entry??{}).sort(),['artifacts','complexityLane','key','maturity','module'],'entry keys');
 demand(entry.key===P061_ADMISSION_ID&&entry.module===`./modules/${P061_ADMISSION_ID}`&&
  entry.maturity==='private-current-js'&&entry.complexityLane==='behavior-heavy','DOM entry');
 demand(artifacts?.kind==='maintained-dom-module-v1'&&
  Object.keys(artifacts).sort().join(',')==='kind,memberManifest,module,sourceRun,timeline',
  'DOM artifacts only; no canvas surrogate');
 for(const [key,path] of [['module',P061_CANONICAL_MODULE_PATH],
  ['timeline',P061_CANONICAL_TIMELINE_PATH],['sourceRun',P061_RUN_PATH],
  ['memberManifest',P061_MEMBER_PATH]])validPin(artifacts[key],path);
 same(packet.audio,P061_AUDIO,'eleven source payloads and qualified transport');
 same(packet.glossary,P061_GLOSSARY,'seven occurrences, six terms, conditional L1');
 same(packet.acceptanceEffects,Object.fromEntries(P061_ACCEPTANCE_KEYS.map(key=>[key,false])),
  'independent acceptance remains false');
 demand(packet.productCalibrationPassed===false&&packet.scaleOutAuthorized===false,
  'no factory scale-out or product calibration promotion');
 validPin(packet.freezeManifest,P061_FREEZE_PATH);
 same(registration,{calibrationId:P061_ADMISSION_CALIBRATION,deploymentScope:'local-only',
  freezeManifest:P061_FREEZE_PATH,freezeManifestBytes:packet.freezeManifest.bytes,
  freezeManifestSha256:packet.freezeManifest.sha256,entries:[entry]},
  'one exact local registration fragment');
 const seal=requireSeal();
 for(const [pin,path] of [[seal.module,P061_CANONICAL_MODULE_PATH],
  [seal.timeline,P061_CANONICAL_TIMELINE_PATH],[seal.run,P061_RUN_PATH],
  [seal.member,P061_MEMBER_PATH]])validPin(pin,path);
 same(artifacts,{kind:'maintained-dom-module-v1',module:seal.module,timeline:seal.timeline,
  sourceRun:seal.run,memberManifest:seal.member},'reviewed immutable DOM pins');
 same(packet.integrity?.sharedDependencies,seal.sharedDependencies,'separate host pins');
 return true;
}

export function validateP061ProofClosure(proof){
 demand(proof?.schemaVersion===1&&proof.kind==='nms-l02-page-proof-v1'&&
  proof.hostContract==='nms-l02-source-bound-host-v1'&&proof.animationId===P061_ADMISSION_ID,
  'page proof identity');
 validPin(proof.freeze,P061_FREEZE_PATH);
 validateP061AdmissionSemantics({...proof.packet,freezeManifest:proof.freeze},proof.registration);
 const seal=requireSeal();
 demand(Array.isArray(seal.pageInputPaths)&&Array.isArray(seal.runInputs)&&
  Array.isArray(seal.runOutputs)&&Array.isArray(seal.sharedDependencies),
  'reviewed finite DOM closure');
 same(seal.pageInputPaths,sorted([...new Set(seal.pageInputPaths)]),'sorted unique page list');
 for(const path of P061_REQUIRED_PAGE_PATHS)
  demand(seal.pageInputPaths.includes(path),`required page path ${path}`);
 for(const pin of [P061_SOURCE_AUDIT,P061_BEHAVIOR_AUDIT,P061_RAW_AUDIO,
  P061_AUDIO_RECEIPT,P061_GLOSSARY_CANDIDATE,P061_GLOSSARY_RECEIPT,
  P061_GLOSSARY_PRODUCT,P061_MAIN_AUDIO,...P061_SOURCE_AUDIO_PAYLOADS])
  same(seal.runInputs.find(row=>row.path===pin.path),pin,`source/run pin ${pin.path}`);
 const own=proof.packet?.integrity?.files;
 demand(proof.packet.integrity.scope==='single-NMS-L02-P061-source-and-implementation'&&
  proof.packet.integrity.completeTransitiveClosure===false&&Array.isArray(own),
  'finite page integrity');
 same(own.map(pin=>pin.path),seal.pageInputPaths,'exact page-owned membership');
 for(const pin of own)validPin(pin,pin.path);
 const byPath=new Map(own.map(pin=>[pin.path,pin]));demand(byPath.size===own.length,'unique page pins');
 for(const pin of [...seal.runInputs,...seal.runOutputs,seal.run,seal.member])
  same(byPath.get(pin.path),pin,`immutable DOM run/input/output ${pin.path}`);
 for(const pin of seal.sharedDependencies)demand(!byPath.has(pin.path),'page/host disjoint');
 demand(Array.isArray(proof.files),'proof files');
 same(proof.files.map(pin=>pin.path),sorted([...seal.pageInputPaths,P061_FREEZE_PATH,P061_FRAGMENT_PATH]),
  'proof file membership');
 for(const pin of proof.files)validPin(pin,pin.path);
 const files=new Map(proof.files.map(pin=>[pin.path,pin]));
 demand(files.size===proof.files.length,'unique proof pins');
 for(const pin of own)same(files.get(pin.path),pin,`proof retains ${pin.path}`);
 same(files.get(P061_FREEZE_PATH),proof.freeze,'freeze pin');
 same(seal.external,P061_EXTERNAL_EXPECTED,'reviewed external source/bank/host seal');
 same(proof.external,P061_EXTERNAL_EXPECTED,'exact physical source/bank/host pins');
 return true;
}
